<?php if(!defined('ABSPATH'))exit; $connected=SEO_Manager_Google::connected(); $sites=(array)seom_get('google_sites',[]); $rows=(array)seom_get('google_analytics_rows',[]); $clicks=$impressions=$position=0.0; foreach($rows as $r){$clicks+=(float)($r['clicks']??0);$impressions+=(float)($r['impressions']??0);$position+=(float)($r['position']??0);} $ctr=$impressions?($clicks/$impressions)*100:0; $avgpos=$rows?($position/count($rows)):0; ?>
