<?php if(isset($_GET['google_sitemap'])): ?><div class="notice notice-<?php echo $_GET['google_sitemap']==='submitted'?'success':'error'; ?>"><p><?php echo $_GET['google_sitemap']==='submitted'?'Sitemap submission request sent.':'Sitemap submission failed.'; ?></p></div><?php endif; ?>
